insert into public.questions (id,title,prompt,options,explanation,category,xp,activity_type) values ('00000000-0000-4000-8000-000000000402','Refatoração de Algoritmo de Busca','Você precisa encontrar um item em uma lista não ordenada. Qual estratégia funciona sem reordenar os dados?','["Busca binária diretamente","Retornar sempre o primeiro item","Percorrer até encontrar o item","Comparar somente o último item"]'::jsonb,'A busca linear percorre a lista e funciona sem exigir ordenação.','Laboratório',150,'multiple_choice') on conflict(id) do nothing;
