insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010000','Condição de aprovação','A aprovação exige nota ≥ 7 E frequência ≥ 75%. Qual estudante satisfaz a regra?','["Nota 8 e frequência 70%","Nota 6 e frequência 90%","Nota 7 e frequência 75%","Nota 6,9 e frequência 74%"]'::jsonb,'As duas condições precisam ser verdadeiras; os limites 7 e 75 estão incluídos.','Exercício','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010001','Acumulador','Um acumulador começa em 2. Para cada valor de [3, 1, 4], ele soma o dobro do valor. Qual o resultado?','["10","18","20","16"]'::jsonb,'2 + 2×3 + 2×1 + 2×4 = 18.','Exercício','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010002','Limite de repetição','Um laço começa com i=0 e repete enquanto i<5, incrementando i em 1 após cada execução. Quantas execuções ocorrem?','["4","6","5","0"]'::jsonb,'O corpo executa para i igual a 0, 1, 2, 3 e 4: cinco vezes.','Exercício','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010003','Negação de regra','O acesso é permitido quando cadastrado E ativo. Qual condição representa corretamente a recusa?','["Não cadastrado E não ativo","Cadastrado OU ativo","Não cadastrado OU não ativo","Cadastrado E não ativo"]'::jsonb,'Pela negação da conjunção, basta não estar cadastrado ou não estar ativo para o acesso ser recusado.','Exercício','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010004','Busca sem resultado','Na busca linear em [8, 3, 6, 1, 9], quantas comparações com elementos são necessárias para concluir que 7 não está presente?','["1","4","5","7"]'::jsonb,'Sem ordenação e sem encontrar o alvo, todos os cinco elementos precisam ser comparados.','Laboratório','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010005','Primeira ocorrência','Uma busca linear retorna assim que encontra o alvo. Para [4, 2, 4, 9] e alvo 4, qual índice, contando a partir de zero, será retornado?','["0","2","4","3"]'::jsonb,'O alvo já está no primeiro elemento, índice zero; a busca termina antes da segunda ocorrência.','Laboratório','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010006','Teste de fronteira','Uma função recebe uma lista e devolve seu primeiro item, mas falha quando não há itens. Qual teste identifica diretamente esse defeito?','["Lista com 100 números","Lista vazia","Lista ordenada com 2 números","Lista de 3 números repetidos"]'::jsonb,'Na lista vazia não existe índice zero. A função precisa tratar esse caso antes de acessar o primeiro item.','Laboratório','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010007','Comparações desnecessárias','Uma busca encontra o alvo no segundo item de uma lista de 100 itens, mas continua percorrendo todos. Se basta saber se o alvo existe, qual mudança mantém o resultado e reduz trabalho?','["Ordenar a lista a cada comparação","Remover itens até sobrar um","Retornar verdadeiro ao encontrar o alvo","Comparar apenas o último item"]'::jsonb,'Encerrar no primeiro acerto é suficiente para verificar existência e evita as comparações restantes.','Laboratório','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010008','Conflito de integração','Duas pessoas alteraram a mesma regra de negócio e produziram resultados incompatíveis. Qual ação permite integrar com critério?','["Escolher sempre a versão mais recente","Definir o resultado esperado com a equipe e executar testes sobre a versão integrada","Apagar todos os testes","Manter as duas regras contraditórias"]'::jsonb,'O comportamento acordado e os testes permitem resolver o conflito com evidência, sem escolher uma versão arbitrariamente.','Dinâmica','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010009','Feedback útil','Um colega entrega um formulário que não identifica o campo com erro. Qual feedback é mais acionável?','["Está ruim","Você não sabe fazer","Tudo precisa mudar","Ao enviar o e-mail vazio, não consigo localizar o erro; destaque esse campo e explique como preenchê-lo"]'::jsonb,'Descrever a situação observada, o impacto e a melhoria torna o feedback específico e verificável.','Dinâmica','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010010','Prioridade da entrega','Faltam duas horas para a entrega. O login falha e um ícone está desalinhado. Qual decisão reduz o maior impedimento de uso?','["Ajustar só o ícone","Corrigir e testar o login antes de polir o ícone","Adicionar três telas novas","Ocultar o botão de login"]'::jsonb,'Uma falha de acesso bloqueia o fluxo principal. Corrigir e testar esse impedimento tem prioridade sobre um ajuste cosmético.','Dinâmica','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010011','Divisão de tarefas','Uma tarefa depende de uma API que ainda não tem contrato definido. Qual combinação permite trabalho paralelo com menor risco de incompatibilidade?','["Cada pessoa inventa campos diferentes","Esperar sem conversar","Combinar campos, erros e exemplos; usar dados de teste compatíveis com o contrato","Remover a validação do cliente"]'::jsonb,'Um contrato compartilhado permite construir as partes em paralelo e testar a integração com os mesmos formatos.','Dinâmica','choice','00000000-0000-4000-8000-000000000014',50,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010012','Laços dependentes','Para i de 1 até 8, um laço interno executa i vezes e incrementa total em 1. total começa em zero. Qual é o valor final?','["16","32","36","64"]'::jsonb,'A soma é 1+2+3+4+5+6+7+8 = 8×9/2 = 36.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010013','Busca binária e limite','Em uma busca binária padrão, cada comparação com o elemento central elimina esse elemento e uma das metades. Para 127 elementos ordenados, qual o máximo de comparações até encontrar um alvo presente?','["6","7","8","127"]'::jsonb,'As faixas máximas têm 127, 63, 31, 15, 7, 3 e 1 elemento. Isso produz no máximo sete comparações.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010014','Atualização sequencial','Inicialmente a=3 e b=5. Execute, nessa ordem: a=a+b; b=a-b; a=a-b. Quais são os valores finais?','["a=3, b=5","a=8, b=3","a=5, b=3","a=5, b=8"]'::jsonb,'Depois das instruções: (8,5), (8,3), (5,3). Cada linha usa os valores atualizados pela anterior.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010015','Tabela de junção','Há dois pedidos do cliente A e um pedido do cliente B. A tabela de contatos possui três contatos de A e dois de B. Ao unir pedidos e contatos apenas por cliente, quantas linhas resultam?','["3","5","6","8"]'::jsonb,'Cada pedido de A combina com três contatos: 2×3=6. O de B combina com dois: 1×2=2. Total: oito.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010016','Condição composta','Uma regra permite acesso quando (idade≥18 OU autorizado) E NÃO bloqueado. Qual caso é permitido?','["Idade 17, autorizado sim, bloqueado não","Idade 20, autorizado sim, bloqueado sim","Idade 17, autorizado não, bloqueado não","Idade 18, autorizado não, bloqueado sim"]'::jsonb,'No primeiro caso a autorização satisfaz a primeira parte e não há bloqueio. Os demais falham em pelo menos uma condição.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010017','Fronteiras de paginação','Uma lista tem 53 itens. As páginas exibem 10 itens, com índices iniciados em zero. Qual faixa de índices pertence à sexta página?','["50 a 59","51 a 53","50 a 52","49 a 52"]'::jsonb,'As cinco primeiras páginas cobrem 0–49. A sexta tem os três itens restantes, índices 50, 51 e 52.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010018','Recorrência','Considere f(0)=1 e, para n>0, f(n)=2×f(n−1)+1. Qual é f(4)?','["16","30","31","32"]'::jsonb,'Os valores sucessivos são 1, 3, 7, 15 e 31.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010019','Transferência consistente','Um saldo A=100 deve transferir 30 para B=20. O débito de A é salvo, mas o crédito de B falha. Qual solução mantém a regra de que a soma dos saldos não muda?','["Repetir só o débito","Ignorar a falha e mostrar sucesso","Agrupar débito e crédito em uma transação que confirme ambos ou reverta ambos","Alterar apenas a tela para mostrar B=50"]'::jsonb,'A transação garante que as duas alterações sejam confirmadas juntas ou que nenhuma permaneça. A soma continua sendo 120.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010020','Custo acumulado','Um algoritmo percorre n elementos uma vez e depois compara todos os pares distintos com i<j. Para n=20, quantas operações são feitas, contando cada visita e cada comparação como uma operação?','["190","200","210","400"]'::jsonb,'São 20 visitas mais 20×19/2=190 pares: total de 210 operações.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010021','Teste que distingue defeito','A regra correta é nota≥7 E presença≥75. Um programa usa OU por engano. Qual entrada faz o programa aprovar enquanto a regra correta reprova?','["Nota 8, presença 80","Nota 6, presença 70","Nota 7, presença 75","Nota 8, presença 70"]'::jsonb,'Com nota 8 e presença 70, apenas a nota passa. OU aprova, enquanto E reprova. As outras entradas não distinguem as duas regras.','Exames','choice','00000000-0000-4000-8000-000000000014',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010022','Demanda no prazo de reposição','O consumo é 18 unidades por dia. O fornecedor leva 6 dias e exige-se estoque de segurança de 30 unidades. Sem variação de demanda, qual é o ponto de reposição?','["108","138","180","48"]'::jsonb,'Demanda no prazo: 18×6=108. Somando 30 unidades de segurança, o ponto de reposição é 138.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010023','Capacidade e ocupação','Um veículo comporta 1.200 kg. Cada caixa tem 18 kg. O limite operacional é 90% da capacidade, e só podem ser transportadas caixas inteiras. Qual o máximo de caixas?','["54","60","66","67"]'::jsonb,'90% de 1.200 é 1.080 kg; 1.080/18=60 caixas.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010024','Descontos sucessivos','Um lote custa R$ 2.000. Aplica-se desconto de 10% e, sobre o valor reduzido, outro de 5%. O frete é R$ 100. Qual o custo final?','["R$ 1.700","R$ 1.800","R$ 1.810","R$ 1.900"]'::jsonb,'2.000×0,90×0,95=1.710. Com frete de 100, o total é 1.810. Descontos sucessivos não são simplesmente somados.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010025','Fluxo do estoque','O estoque inicial é 120. Entram 80 unidades e saem 135. Das unidades restantes, 15 estão avariadas e 20 reservadas. Quantas estão disponíveis para novas vendas?','["30","50","65","85"]'::jsonb,'O saldo físico é 120+80−135=65. Descontando 15 avariadas e 20 reservadas, ficam 30 disponíveis.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010026','Gargalo de processo','Três etapas em série têm capacidades de 80, 50 e 65 peças por hora. Sem estoques intermediários suficientes para alterar o regime estável, qual mudança aumenta a capacidade máxima da linha?','["Aumentar apenas a primeira para 100","Aumentar a segunda para 60","Aumentar apenas a terceira para 90","Reduzir a primeira para 70"]'::jsonb,'A segunda etapa limita a linha a 50. Ao elevá-la a 60, ela ainda é o gargalo, mas o limite da linha aumenta para 60.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010027','Roteiro com janelas','Um veículo sai às 8h. Leva 35 min até A, descarrega por 20 min e leva 40 min até B. B só recebe a partir de 10h. Quanto tempo aguardará em B?','["15 minutos","25 minutos","35 minutos","45 minutos"]'::jsonb,'Chega a A às 8h35, sai às 8h55 e chega a B às 9h35. Aguarda 25 minutos até as 10h.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010028','Produtividade proporcional','Quatro pessoas separam 240 pedidos em 3 horas, com produtividade igual e constante. Quantos pedidos seis pessoas separam em 5 horas, sem gargalos adicionais?','["400","480","600","720"]'::jsonb,'Cada pessoa separa 240/(4×3)=20 pedidos por hora. Seis pessoas em cinco horas separam 6×5×20=600.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010029','Média ponderada','Foram compradas 40 unidades a R$ 12 e 60 a R$ 18, sem outros custos. Qual o custo médio ponderado por unidade?','["R$ 15,00","R$ 15,60","R$ 16,00","R$ 16,80"]'::jsonb,'O custo total é 40×12+60×18=1.560 para 100 unidades; a média ponderada é 15,60.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010030','Índice de atendimento','De 250 pedidos, 225 chegaram no prazo. Entre esses 225, 15 estavam incompletos. Considerando sucesso apenas entrega no prazo E completa, qual o percentual de sucesso?','["84%","90%","94%","96%"]'::jsonb,'Os pedidos que atendem aos dois critérios são 225−15=210. 210/250×100=84%.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,subject_id,xp,activity_type) values ('00000000-0000-4000-8000-000000010031','Comparação de fornecedores','Para 120 unidades, A cobra R$ 25 por unidade e R$ 180 de frete. B cobra R$ 27 por unidade, desconto de 5% sobre os produtos e frete grátis. Qual proposta é mais barata e por quanto?','["A, por R$ 60","A, por R$ 102","B, por R$ 60","B, por R$ 102"]'::jsonb,'A custa 120×25+180=3.180. B custa 120×27×0,95=3.078. B é mais barato em 102 reais.','Exames','choice','00000000-0000-4000-8000-000000000011',80,'multiple_choice') on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012000','Decisões em Python','Qual trecho imprime aprovado apenas se nota for pelo menos 7?','["if nota >= 7:\n    print(\"aprovado\")","if nota > 7\nprint(\"aprovado\")","if nota = 7:\n    print(\"aprovado\")"]'::jsonb,'A comparação >= inclui 7; a condição termina com dois-pontos e o comando fica indentado.','Atividade de trilha','choice','multiple_choice','00000000-0000-4000-8000-000000000014','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012001','Completar uma repetição','Complete apenas a palavra: for numero ___ range(1, 4):','[]'::jsonb,'A palavra in conecta a variável do laço à sequência percorrida.','Atividade de trilha','blank','fill_blank','00000000-0000-4000-8000-000000000014','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012002','Seu programa de soma','Escreva um programa Python que leia dois inteiros com input() e imprima somente a soma.','[]'::jsonb,'Converta as duas entradas para inteiro e use print(a + b). O programa deve funcionar também com zero e valores negativos.','Atividade de trilha','blank','code_practice','00000000-0000-4000-8000-000000000014','{"language":"python","starter":"a = int(input())\nb = int(input())\n# Imprima a soma\n","tests":[{"stdin":"3\n4","stdout":"7"},{"stdin":"-2\n5","stdout":"3"},{"stdin":"0\n0","stdout":"0"}]}'::jsonb,100) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012003','Organizar um programa','Ordene as etapas de um programa que calcula uma soma.','["Ler os dois valores","Converter os textos em números","Calcular a soma","Mostrar o resultado"]'::jsonb,'A conversão depende das entradas; a soma depende dos números; a saída depende do resultado.','Atividade de trilha','ordering','ordering','00000000-0000-4000-8000-000000000014','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012004','Identificar um erro','O código const total = "3" + "4" produz "34". Como obter o número 7?','["Usar Number(\"3\") + Number(\"4\")","Usar \"3\" + Number(\"4\")","Usar String(3) + String(4)"]'::jsonb,'Converter as duas entradas com Number faz uma soma numérica. Se uma delas continuar sendo string, pode ocorrer concatenação.','Atividade de trilha','choice','multiple_choice','00000000-0000-4000-8000-000000000014','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012005','Somar com JavaScript','Leia dois inteiros com input() e escreva somente a soma usando console.log().','[]'::jsonb,'Use console.log(a + b) após converter as duas entradas com Number.','Atividade de trilha','blank','code_practice','00000000-0000-4000-8000-000000000014','{"language":"javascript","starter":"const a = Number(input());\nconst b = Number(input());\n// Mostre a soma\n","tests":[{"stdin":"3\n4","stdout":"7"},{"stdin":"-2\n5","stdout":"3"},{"stdin":"0\n0","stdout":"0"}]}'::jsonb,100) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012006','Construir uma página semântica','Crie um h1 com o texto Meu curso, um link dentro de nav apontando para #conteudo e um main com id conteudo.','[]'::jsonb,'O título h1 identifica a página, nav reúne a navegação e main delimita o conteúdo principal. O destino do link precisa existir.','Atividade de trilha','blank','code_practice','00000000-0000-4000-8000-000000000014','{"language":"web","starter":"<!doctype html>\n<html lang=\"pt-BR\">\n<head><meta charset=\"UTF-8\"><style>body { font-family: sans-serif; padding: 16px; }</style></head>\n<body>\n<!-- Escreva o título, a navegação e o conteúdo principal -->\n</body>\n</html>","webRules":[{"selector":"h1","text":"Meu curso"},{"selector":"nav a","attribute":"href","value":"#conteudo"},{"selector":"main#conteudo"}]}'::jsonb,100) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012007','Comparar dois formulários','Qual formulário permite identificar o campo mesmo depois de começar a digitar?','["Formulário A","Formulário B"]'::jsonb,'O formulário B mantém um rótulo externo, que continua indicando a finalidade do campo durante o preenchimento.','Atividade de trilha','choice','image_identification','00000000-0000-4000-8000-000000000014','{"image":"/assets/activities/formularios.svg","imageAlt":"A: campo apenas com exemplo dentro. B: rótulo E-mail acima do campo, que permanece visível."}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012008','Planejar uma avaliação','Organize uma rodada de melhoria baseada em evidências.','["Observar a dificuldade de uso","Definir o problema","Criar uma alternativa","Testar a alternativa com pessoas"]'::jsonb,'A observação informa o problema; a alternativa responde a ele e o teste verifica se a mudança ajudou.','Atividade de trilha','ordering','ordering','00000000-0000-4000-8000-000000000014','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012009','Interpretar uma topologia','No desenho, se apenas o cabo marcado X for desconectado, quais computadores perdem o enlace com o switch?','["Apenas o computador A","Apenas o computador B","Todos os computadores"]'::jsonb,'O X está no enlace de B. A e C continuam ligados ao switch por seus próprios cabos.','Atividade de trilha','choice','image_identification','00000000-0000-4000-8000-000000000017','{"image":"/assets/activities/topologia.svg","imageAlt":"Switch central ligado separadamente aos computadores A, B e C. O cabo entre o switch e B está marcado com X."}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012010','Diagnóstico por evidências','Um computador alcança o roteador e um servidor externo por endereço IP, mas não resolve nomes de domínio. O que investigar primeiro?','["A configuração e a resposta do DNS","Trocar o monitor","Apagar todos os arquivos do computador"]'::jsonb,'Os testes já indicam conectividade local e externa por IP. A falha específica de nomes aponta primeiro para resolução DNS.','Atividade de trilha','choice','case_study','00000000-0000-4000-8000-000000000017','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012011','Calcular estoque disponível','Há 120 unidades. Chegam 80, saem 135, 15 estão avariadas e 20 reservadas. Quantas unidades estão disponíveis?','[]'::jsonb,'Saldo físico: 120 + 80 − 135 = 65. Disponível: 65 − 15 − 20 = 30 unidades.','Atividade de trilha','blank','calculation','00000000-0000-4000-8000-000000000011','{"unit":"unidades"}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012012','Organizar a expedição','Ordene uma sequência de preparação de pedido.','["Separar os produtos","Conferir itens e quantidades","Embalar e identificar","Registrar a saída"]'::jsonb,'Separar e conferir antes de embalar reduz o risco de enviar itens incorretos.','Atividade de trilha','ordering','ordering','00000000-0000-4000-8000-000000000011','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012013','Completar uma frase','Complete com o verbo estudar no presente: As estudantes ___ todos os dias.','[]'::jsonb,'O sujeito As estudantes está no plural; a forma correspondente no presente é estudam.','Atividade de trilha','blank','fill_blank','00000000-0000-4000-8000-000000000010','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012014','Revisar uma mensagem','Você precisa receber uma revisão até sexta. Qual mensagem comunica melhor o pedido?','["Revisa isso aí.","Você nunca ajuda com nada.","Você pode revisar o parágrafo de apresentação até sexta? Preciso verificar se a ideia principal está clara."]'::jsonb,'A terceira mensagem especifica a tarefa, o prazo e o objetivo da revisão, sem julgamento pessoal.','Atividade de trilha','choice','case_study','00000000-0000-4000-8000-000000000010','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012015','Identificar estruturas celulares','Qual número indica o núcleo no esquema?','["1","2","3"]'::jsonb,'O número 2 aponta para o núcleo. O 1 indica a membrana e o 3, o citoplasma.','Atividade de trilha','choice','image_identification','00000000-0000-4000-8000-000000000012','{"image":"/assets/activities/celula.svg","imageAlt":"Esquema simplificado: 1 aponta para o contorno externo; 2 aponta para a estrutura arredondada central; 3 aponta para a região interna ao redor dela."}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012016','Classificar grupos de plantas','Relacione os grupos às características.','["Não possuem vasos condutores","Têm sementes sem frutos","Produzem flores e frutos"]'::jsonb,'As características de vasos, sementes e frutos ajudam a distinguir esses grupos de plantas.','Atividade de trilha','matching','matching','00000000-0000-4000-8000-000000000012','{"labels":["Briófitas","Gimnospermas","Angiospermas"]}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012017','Calcular velocidade média','Uma pessoa percorre 120 metros em 60 segundos e depois 60 metros em 30 segundos. Qual é a rapidez média de todo o trajeto?','[]'::jsonb,'A distância total é 180 m e o tempo total é 90 s. Logo, 180/90 = 2 m/s.','Atividade de trilha','blank','calculation','00000000-0000-4000-8000-000000000013','{"unit":"m/s"}'::jsonb,60) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,kind,activity_type,subject_id,payload,xp) values ('00000000-0000-4000-8000-000000012018','Interpretar uma medição','Dois registros descrevem a mesma distância: 1,5 km e 1500 m. Qual conclusão é correta?','["São distâncias diferentes porque os números diferem","São equivalentes após converter quilômetros para metros","O segundo registro é sempre mais preciso"]'::jsonb,'1 km corresponde a 1000 m, então 1,5 km = 1500 m. A escrita, sozinha, não permite concluir a precisão da medição.','Atividade de trilha','choice','case_study','00000000-0000-4000-8000-000000000013','{}'::jsonb,60) on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000200','Fundamentos','Um algoritmo é uma sequência finita de passos para resolver um problema. Antes de escrever código, descreva a entrada, o processamento e a saída.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000200','Variáveis','Variáveis associam um nome a um valor. Em Dart, int armazena inteiros; double armazena decimais; String representa texto; bool representa verdadeiro ou falso.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000302','00000000-0000-4000-8000-000000000200','Lógica','Uma condição produz verdadeiro ou falso. Combine comparações com && (e), || (ou) e ! (negação).
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000303','00000000-0000-4000-8000-000000000200','Maratona 1','Planeje um programa de cadastro de três produtos. Para cada um, registre nome, preço e quantidade. Calcule o total do estoque.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000304','00000000-0000-4000-8000-000000000200','Condicionais','if executa um bloco quando sua condição é verdadeira. else permite tratar o caso contrário.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000305','00000000-0000-4000-8000-000000000200','Loops','Use um laço quando uma operação precisa se repetir. Um for tem inicialização, condição e atualização.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000306','00000000-0000-4000-8000-000000000200','Arrays','Em Dart, List organiza valores em sequência. O primeiro índice é 0.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000320','00000000-0000-4000-8000-000000000201','Requisições HTTP','O cliente envia uma requisição a um servidor. Método, caminho, cabeçalhos e corpo descrevem a operação. A resposta inclui status e conteúdo.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000321','00000000-0000-4000-8000-000000000201','APIs REST','Recursos podem ser representados por endereços como /produtos. Defina contratos de entrada e saída, valide dados no servidor e diferencie erros de validação de falhas internas.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000322','00000000-0000-4000-8000-000000000201','Microservices Patterns','Separar serviços cria limites claros, mas também falhas de rede e desafios de consistência. Use timeouts, operações idempotentes e contratos versionados.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003000','00000000-0000-4000-8000-000000002000','HTML semântico','HTML descreve a estrutura do documento. Use títulos em ordem e elementos como main, nav e button conforme sua função. Um botão executa uma ação; um link leva a outro endereço. Crie no papel o esqueleto semântico de uma página de estudos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003001','00000000-0000-4000-8000-000000002000','CSS responsivo','CSS define apresentação. Use grid ou flex para distribuir conteúdo, unidades flexíveis e limites de largura. Comece pela tela pequena; mantenha rótulos legíveis e foco visível. Descreva como sua página se reorganiza ao ganhar espaço.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003002','00000000-0000-4000-8000-000000002000','Publicação acessível','Antes de publicar, verifique títulos, alternativas textuais, contraste e navegação por teclado. Teste links e formulários. Descreva três verificações que faria em uma página de estudos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003010','00000000-0000-4000-8000-000000002001','Entender o problema','Comece pelo problema e pelo contexto. Uma entrevista investiga experiências, não confirma uma solução pronta. Escreva uma pergunta aberta sobre como estudantes encontram materiais e indique qual dúvida a pesquisa resolve.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003011','00000000-0000-4000-8000-000000002001','Estruturar a interface','Agrupe informações relacionadas, estabeleça uma hierarquia de títulos e mantenha padrões de navegação. Desenhe uma tela de biblioteca com busca, matérias e indicação de leitura. Explique a prioridade visual escolhida.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003012','00000000-0000-4000-8000-000000002001','Testar com pessoas','No teste de usabilidade, proponha uma tarefa realista e observe sem ensinar o caminho. Registre erros, hesitações e comentários. Planeje uma tarefa para encontrar um material e descreva como perceberá que foi concluída.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003020','00000000-0000-4000-8000-000000002002','Rede local','DNS resolve nomes. Um roteador encaminha pacotes. Uma conexão Wi-Fi local não garante acesso à internet.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003021','00000000-0000-4000-8000-000000002002','Endereçamento e DNS','DNS resolve nomes. Um roteador encaminha pacotes. Uma conexão Wi-Fi local não garante acesso à internet.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003022','00000000-0000-4000-8000-000000002002','Diagnóstico de conexão','Crie um roteiro de diagnóstico quando um dispositivo conecta ao Wi-Fi mas não abre sites. Separe rede local, internet e resolução de nomes.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003030','00000000-0000-4000-8000-000000002003','Grandezas elétricas','Resistores limitam corrente. Resistência é medida em ohms, corrente em amperes e tensão em volts. Confira limites dos componentes.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003031','00000000-0000-4000-8000-000000002003','Circuito com resistor','Resistores limitam corrente. Resistência é medida em ohms, corrente em amperes e tensão em volts. Confira limites dos componentes.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003032','00000000-0000-4000-8000-000000002003','Simulação de LED','Desenhe no papel um circuito de LED com fonte de baixa tensão e resistor. Explique a função do resistor e a polaridade. Não use a rede elétrica.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003040','00000000-0000-4000-8000-000000002004','Fluxo de materiais','O saldo é 20 − 7 = 13. O controle registra movimentações; a distribuição conecta o estoque ao destino, sem eliminar todos os riscos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003041','00000000-0000-4000-8000-000000002004','Controle de estoque','O saldo é 20 − 7 = 13. O controle registra movimentações; a distribuição conecta o estoque ao destino, sem eliminar todos os riscos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003042','00000000-0000-4000-8000-000000002004','Preparação de pedidos','Planeje o envio de um pedido com três produtos. Descreva conferência, embalagem e registro da saída.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003050','00000000-0000-4000-8000-000000002005','Leitura ativa','Proparoxítonas têm a antepenúltima sílaba tônica. Substantivos nomeiam; verbos expressam ação ou estado; adjetivos caracterizam.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003051','00000000-0000-4000-8000-000000002005','Ortografia e revisão','Proparoxítonas têm a antepenúltima sílaba tônica. Substantivos nomeiam; verbos expressam ação ou estado; adjetivos caracterizam.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003052','00000000-0000-4000-8000-000000002005','Comunicação de projetos','Escreva um parágrafo apresentando um projeto da escola. Identifique a ideia principal e revise a ortografia.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003060','00000000-0000-4000-8000-000000002006','Células e organelas','Angiospermas produzem flores e frutos; briófitas não possuem vasos verdadeiros. Cloroplastos participam da fotossíntese.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003061','00000000-0000-4000-8000-000000002006','Grupos de plantas','Angiospermas produzem flores e frutos; briófitas não possuem vasos verdadeiros. Cloroplastos participam da fotossíntese.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003062','00000000-0000-4000-8000-000000002006','Observação científica','Observe uma planta sem arrancá-la. Descreva raiz quando visível, caule e folhas; explique uma função de cada órgão observado.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003070','00000000-0000-4000-8000-000000002007','Grandezas e unidades','Força é medida em newtons; energia em joules; potência em watts. Massa é medida em quilogramas, enquanto peso é uma força.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003071','00000000-0000-4000-8000-000000002007','Movimento','Força é medida em newtons; energia em joules; potência em watts. Massa é medida em quilogramas, enquanto peso é uma força.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003072','00000000-0000-4000-8000-000000002007','Medição e análise','Descreva como medir a velocidade média em um trajeto seguro. Apresente valores hipotéticos, unidades e cálculo.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003080','00000000-0000-4000-8000-000000002008','Reconhecer habilidades','Habilidades técnicas e de colaboração podem ser demonstradas por projetos escolares. Liste uma situação, a ação que realizou e o resultado observado. Evite atribuir a si resultados que não foram medidos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003081','00000000-0000-4000-8000-000000002008','Documentar projetos','Um portfólio explica contexto, contribuição, decisões e aprendizados. Escolha um projeto e escreva um parágrafo para cada item. Diferencie trabalho individual de decisões feitas em equipe.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003082','00000000-0000-4000-8000-000000002008','Preparar uma candidatura','Leia os requisitos da vaga, compare com experiências reais e adapte a apresentação. Não invente competências. Prepare uma mensagem curta com interesse, evidência de aprendizado e disponibilidade, sem incluir documentos pessoais.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004000','00000000-0000-4000-8000-000000002100','Decisões em Python','Use if para executar um bloco quando uma condição for verdadeira. Em Python, a indentação delimita o bloco e os dois-pontos encerram a linha da condição.',0,null,100,'00000000-0000-4000-8000-000000012000') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004001','00000000-0000-4000-8000-000000002100','Completar uma repetição','range(1, 4) produz 1, 2 e 3. Em um laço for, escrevemos a variável, a palavra in e a sequência que será percorrida.',1,'00000000-0000-4000-8000-000000004000',100,'00000000-0000-4000-8000-000000012001') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004002','00000000-0000-4000-8000-000000002100','Seu programa de soma','input() lê uma linha de entrada como texto. int() converte o texto em inteiro. print() mostra o resultado. Leia dois números, um por linha, e imprima apenas a soma. Teste também números negativos e zero.',2,'00000000-0000-4000-8000-000000004001',100,'00000000-0000-4000-8000-000000012002') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004003','00000000-0000-4000-8000-000000002101','Organizar um programa','Um programa costuma ler entradas, processar valores e apresentar uma saída. A ordem precisa respeitar a dependência entre as informações.',0,null,100,'00000000-0000-4000-8000-000000012003') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004004','00000000-0000-4000-8000-000000002101','Identificar um erro','Em JavaScript, input() deste ambiente devolve texto. Number() converte uma entrada numérica. Somar duas strings concatena seus caracteres.',1,'00000000-0000-4000-8000-000000004003',100,'00000000-0000-4000-8000-000000012004') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004005','00000000-0000-4000-8000-000000002101','Somar com JavaScript','Neste ambiente, input() lê uma linha. Use Number(input()) para converter cada entrada e console.log() para mostrar a resposta. O editor executa JavaScript; não oferece APIs de página nem bibliotecas externas.',2,'00000000-0000-4000-8000-000000004004',100,'00000000-0000-4000-8000-000000012005') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004006','00000000-0000-4000-8000-000000002000','Construir uma página semântica','Uma página pode ter um título h1, uma navegação nav e a área principal main. Um link href="#conteudo" aponta para o elemento id="conteudo". Escreva o documento completo e experimente CSS dentro de style. A prévia também aceita JavaScript dentro de script; a avaliação desta etapa verifica a estrutura HTML solicitada.',3,'00000000-0000-4000-8000-000000003002',100,'00000000-0000-4000-8000-000000012006') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004007','00000000-0000-4000-8000-000000002001','Comparar dois formulários','Uma interface precisa informar claramente quais dados são pedidos. Um rótulo permanente continua visível durante a digitação. Texto de exemplo sozinho não substitui um rótulo.',3,'00000000-0000-4000-8000-000000003012',100,'00000000-0000-4000-8000-000000012007') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004008','00000000-0000-4000-8000-000000002001','Planejar uma avaliação','Antes de alterar uma interface, investigue a dificuldade, proponha uma mudança e observe pessoas usando o protótipo.',4,'00000000-0000-4000-8000-000000004007',100,'00000000-0000-4000-8000-000000012008') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004009','00000000-0000-4000-8000-000000002002','Interpretar uma topologia','Em uma topologia em estrela, cada computador se conecta a um equipamento central. Uma interrupção no cabo de um computador afeta aquele enlace; a falha do equipamento central afeta toda a rede ligada a ele.',3,'00000000-0000-4000-8000-000000003022',100,'00000000-0000-4000-8000-000000012009') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004010','00000000-0000-4000-8000-000000002002','Diagnóstico por evidências','Separe os testes de conexão: enlace local, acesso ao roteador, acesso externo por endereço e resolução de nomes. Um problema de nomes não significa que todo o enlace caiu.',4,'00000000-0000-4000-8000-000000004009',100,'00000000-0000-4000-8000-000000012010') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004011','00000000-0000-4000-8000-000000002004','Calcular estoque disponível','Estoque disponível para novas vendas é o saldo físico menos as unidades já reservadas ou indisponíveis.',3,'00000000-0000-4000-8000-000000003042',100,'00000000-0000-4000-8000-000000012011') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004012','00000000-0000-4000-8000-000000002004','Organizar a expedição','A conferência precisa ocorrer antes de lacrar a embalagem. O registro da saída deve refletir o pedido efetivamente preparado.',4,'00000000-0000-4000-8000-000000004011',100,'00000000-0000-4000-8000-000000012012') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004013','00000000-0000-4000-8000-000000002005','Completar uma frase','A concordância verbal relaciona o verbo ao sujeito. Com sujeito no plural, use a forma verbal adequada ao plural no contexto solicitado.',3,'00000000-0000-4000-8000-000000003052',100,'00000000-0000-4000-8000-000000012013') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004014','00000000-0000-4000-8000-000000002005','Revisar uma mensagem','Uma mensagem de projeto deve deixar claros o pedido, o prazo e a informação necessária, mantendo um tom respeitoso.',4,'00000000-0000-4000-8000-000000004013',100,'00000000-0000-4000-8000-000000012014') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004015','00000000-0000-4000-8000-000000002006','Identificar estruturas celulares','Em um esquema simplificado de célula eucariótica, o núcleo abriga o material genético. A membrana delimita a célula e o citoplasma ocupa o espaço interno ao redor das estruturas.',3,'00000000-0000-4000-8000-000000003062',100,'00000000-0000-4000-8000-000000012015') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004016','00000000-0000-4000-8000-000000002006','Classificar grupos de plantas','Briófitas não possuem vasos condutores; gimnospermas têm sementes sem frutos; angiospermas produzem flores e frutos.',4,'00000000-0000-4000-8000-000000004015',100,'00000000-0000-4000-8000-000000012016') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004017','00000000-0000-4000-8000-000000002007','Calcular velocidade média','A rapidez média é a distância total percorrida dividida pelo tempo total. Use unidades compatíveis e inclua intervalos de parada quando eles fizerem parte do tempo observado.',3,'00000000-0000-4000-8000-000000003072',100,'00000000-0000-4000-8000-000000012017') on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000004018','00000000-0000-4000-8000-000000002007','Interpretar uma medição','Para comparar medições, registre as unidades e converta os valores para a mesma unidade antes de calcular.',4,'00000000-0000-4000-8000-000000004017',100,'00000000-0000-4000-8000-000000012018') on conflict(id) do nothing;
